"""L10M conservative closed-loop target policy with steering hysteresis."""

# EVOLVE-BLOCK-START
def decide(observation, memory):
    """Apply a safety gate, confirm tracking, and steer with bounded hysteresis."""
    memory = dict(memory or {})
    state = memory.get("state", "IDLE")
    scan_direction = memory.get("scan_direction", "SCAN_LEFT")
    scan_ticks = int(memory.get("scan_ticks", 0))
    previous_action = memory.get("last_action", "")

    visible = bool(observation["target_visible"])
    bearing = float(observation["target_bearing"])
    distance = observation["target_distance_class"]
    target_confidence = float(observation["target_confidence"])
    identity_confidence = float(observation["target_identity_confidence"])
    track_age = int(observation["track_age"])
    lost_steps = int(observation["lost_steps"])
    safety_confidence = float(observation["safety_confidence"])
    closing_risk = float(observation["closing_risk"])
    heading_error = abs(float(observation["heading_error"]))

    def emit(action, confidence, next_state):
        memory["state"] = next_state
        memory["last_action"] = action
        return action, confidence, memory

    if safety_confidence < 0.60 or closing_risk >= 0.75:
        return emit("STOP", 0.99, "STOPPED")

    confirmed = (
        visible
        and target_confidence >= 0.55
        and identity_confidence >= 0.60
    )
    if not confirmed:
        if state in {"LOCKED", "APPROACH", "VERIFY", "REACQUIRE"} or lost_steps > 0:
            if lost_steps <= 1:
                return emit("STOP", 0.92, "REACQUIRE")
            scan_ticks += 1
            if scan_ticks >= 2:
                scan_direction = (
                    "SCAN_RIGHT" if scan_direction == "SCAN_LEFT" else "SCAN_LEFT"
                )
                scan_ticks = 0
            memory["scan_direction"] = scan_direction
            memory["scan_ticks"] = scan_ticks
            return emit(scan_direction, 0.75, "REACQUIRE")
        return emit(scan_direction, 0.72, "SEARCH")

    memory["scan_ticks"] = 0
    memory["scan_direction"] = scan_direction

    if track_age < 2:
        return emit("SLOW_DOWN", 0.80, "VERIFY")

    if distance == "near" and heading_error <= 15.0 and identity_confidence >= 0.80:
        return emit("ARRIVED", 0.96, "ARRIVED")

    left_available = bool(observation["corridor_left"])
    right_available = bool(observation["corridor_right"])
    center_available = bool(observation["corridor_center"])

    if distance == "near":
        desired = "VEER_LEFT" if bearing < 0.0 else "VEER_RIGHT"
        if desired == "VEER_LEFT" and left_available:
            return emit(desired, 0.88, "APPROACH")
        if desired == "VEER_RIGHT" and right_available:
            return emit(desired, 0.88, "APPROACH")
        if center_available:
            return emit("FORWARD", 0.84, "APPROACH")
        return emit("STOP", 0.98, "STOPPED")

    # Use a wider engage threshold and a narrower release threshold to prevent
    # rapid left/right instruction flips while the target is near center.
    engage = 14.0
    release = 7.0
    if previous_action == "VEER_LEFT" and bearing < release:
        if left_available:
            return emit("VEER_LEFT", 0.88, "APPROACH")
    elif previous_action == "VEER_RIGHT" and bearing > -release:
        if right_available:
            return emit("VEER_RIGHT", 0.88, "APPROACH")

    if bearing <= -engage and left_available:
        return emit("VEER_LEFT", 0.90, "APPROACH")
    if bearing >= engage and right_available:
        return emit("VEER_RIGHT", 0.90, "APPROACH")
    if center_available:
        return emit("FORWARD", 0.92, "APPROACH")
    if bearing < 0.0 and left_available:
        return emit("VEER_LEFT", 0.82, "APPROACH")
    if bearing > 0.0 and right_available:
        return emit("VEER_RIGHT", 0.82, "APPROACH")
    return emit("STOP", 0.98, "STOPPED")
# EVOLVE-BLOCK-END
